public class Main {
    static long gcd(long a, long b) {
        while (b != 0) {
            long remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = Long.parseLong(sc.next());
        long b = Long.parseLong(sc.next());
        long g = gcd(a, b);
        long lcm = (a / g) * b;
        System.out.println(g);
        System.out.println(lcm);
    }
}

