public class Main {
    static boolean isPrime(long n) {
        if (n < 2) {
            return false;
        }
        for (long d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                return false;
            }
        }
        return true;
    }

    static int nextPrime(int p) {
        int candidate = p + 1;
        while (!isPrime(candidate)) {
            candidate++;
        }
        return candidate;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int count = 0;
        for (int start = 2; start < n; start = nextPrime(start)) {
            int sum = start;
            int terms = 1;
            int p = start;
            while (sum < n) {
                p = nextPrime(p);
                sum += p;
                terms++;
            }
            if (sum == n && terms >= 2) {
                count++;
            }
        }
        System.out.println(count);
    }
}

